import DashboardLayout from "@/components/DashboardLayout";
import { EmptyPanel } from "@/components/campuswear/EmptyPanel";
import { OfflinePanel } from "@/components/campuswear/OfflinePanel";
import { isStalledWithoutData } from "@/lib/queryState";
import { PageIntro } from "@/components/campuswear/PageIntro";
import { ProductPhotoAdjuster } from "@/components/campuswear/ProductPhotoAdjuster";
import { ProductVisual } from "@/components/campuswear/ProductVisual";
import { StatusBadge } from "@/components/campuswear/StatusBadge";
import { WorkspaceGate } from "@/components/campuswear/WorkspaceGate";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle, AlertDialogTrigger } from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { formatPeso } from "@/lib/format";
import { toFormNumber } from "@/lib/productFormNumbers";
import { createManagedProduct, deleteManagedProduct, listManagedProducts, ProductDeleteBlockedError, setManagedProductVisibility, updateManagedProduct, uploadProductImage, vendorManagedProductsQueryKey, type ManagedProduct } from "@/lib/supabaseCatalog";
import { useAuth } from "@/_core/hooks/useAuth";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { zodResolver } from "@hookform/resolvers/zod";
import { CircleHelp, Edit3, PackageOpen, Plus, Save, Trash2 } from "lucide-react";
import { useFieldArray, useForm } from "react-hook-form";
import { toast } from "sonner";
import { z } from "zod";
import { vendorNavigation, vendorPrimaryAction } from "./workspace";

const productSchema = z.object({
  name: z.string().min(3, "Product name is required."),
  description: z.string().min(10, "Add a short helpful description."),
  price: z.number().positive("Enter a valid Philippine peso price."),
  variants: z.array(z.object({ size: z.string().min(1, "Enter a size."), sku: z.string().min(3, "Enter an SKU."), quantity: z.number().int().min(0), lowStockThreshold: z.number().int().min(0) })).min(1),
});
type ProductForm = z.infer<typeof productSchema>;

function ProductEditor({ product, productsQueryKey }: { product: ManagedProduct; productsQueryKey: readonly unknown[] }) {
  const queryClient = useQueryClient();
  const form = useForm({ defaultValues: { name: product.name, description: product.description, price: product.priceInCentavos / 100, isActive: product.isActive } });
  const update = useMutation({
    mutationFn: updateManagedProduct,
    onSuccess: () => { toast.success("Product updated."); void queryClient.invalidateQueries({ queryKey: productsQueryKey }); void queryClient.invalidateQueries({ queryKey: ["supabase-catalog"] }); },
    onError: error => toast.error(error instanceof Error ? error.message : "Product changes could not be saved."),
  });
  const hide = useMutation({
    mutationFn: setManagedProductVisibility,
    onSuccess: () => { toast.success("Product hidden from students. Its order history is unchanged."); void queryClient.invalidateQueries({ queryKey: productsQueryKey }); void queryClient.invalidateQueries({ queryKey: ["supabase-catalog"] }); },
    onError: error => toast.error(error instanceof Error ? error.message : "The product could not be hidden."),
  });
  const remove = useMutation({
    mutationFn: deleteManagedProduct,
    onSuccess: result => { toast.success(result.imageRemoved ? "Product deleted." : "Product deleted. Its stored image may need owner cleanup."); void queryClient.invalidateQueries({ queryKey: productsQueryKey }); void queryClient.invalidateQueries({ queryKey: ["supabase-catalog"] }); },
    onError: error => {
      if (error instanceof ProductDeleteBlockedError) {
        toast.error(error.message, product.isActive ? { action: { label: "Hide instead", onClick: () => hide.mutate({ id: product.id, isActive: false }) } } : undefined);
        void queryClient.invalidateQueries({ queryKey: productsQueryKey });
        return;
      }
      toast.error(error instanceof Error ? error.message : "The product could not be deleted.");
    },
  });

  return <><details className="mt-4 rounded-xl border border-border bg-muted/45 p-4"><summary className="flex cursor-pointer list-none items-center gap-2 text-sm font-bold text-primary"><Edit3 className="size-4" />Edit product details</summary><form onSubmit={form.handleSubmit(values => update.mutate({ id: product.id, name: values.name, description: values.description, priceInCentavos: Math.round(values.price * 100), isActive: values.isActive }))} className="mt-4 grid gap-3 sm:grid-cols-2"><label className="text-xs font-bold">Product name<Input className="mt-1.5 h-10 bg-card" {...form.register("name")} /></label><label className="text-xs font-bold">Price (PHP)<Input className="mt-1.5 h-10 bg-card" type="number" min="1" step="0.01" inputMode="decimal" {...form.register("price", { setValueAs: toFormNumber })} /></label><label className="sm:col-span-2 text-xs font-bold">Description<Textarea className="mt-1.5 min-h-20 bg-card" {...form.register("description")} /></label><label className="flex items-center gap-2 text-xs font-bold"><input type="checkbox" className="size-4 accent-primary" {...form.register("isActive")} />Visible to students</label><div className="flex justify-end"><Button size="sm" type="submit" disabled={update.isPending} className="gap-1.5"><Save className="size-3.5" />{update.isPending ? "Saving…" : "Save changes"}</Button></div></form></details><AlertDialog><AlertDialogTrigger asChild><Button type="button" variant="ghost" size="sm" className="mt-3 min-h-11 w-full justify-center gap-1.5 text-destructive hover:bg-destructive/10 hover:text-destructive"><Trash2 className="size-4" aria-hidden="true" />Delete product</Button></AlertDialogTrigger><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Delete “{product.name}”?</AlertDialogTitle><AlertDialogDescription>This permanently removes this product and its size-level inventory when it has no order history. Products referenced by an order cannot be deleted; hide them instead so historical records remain intact.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel disabled={remove.isPending}>Keep product</AlertDialogCancel><AlertDialogAction disabled={remove.isPending} className="bg-destructive text-destructive-foreground hover:bg-destructive/90" onClick={() => remove.mutate({ id: product.id })}>{remove.isPending ? "Deleting…" : "Delete product"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></>;
}

function VariantFields({ form, variants }: { form: ReturnType<typeof useForm<ProductForm>>; variants: ReturnType<typeof useFieldArray<ProductForm, "variants">> }) {
  return <div className="mt-4 space-y-3">{variants.fields.map((field, index) => <div key={field.id} className="rounded-xl border border-border bg-muted/45 p-3"><div className="grid gap-3 sm:grid-cols-[0.8fr_1.5fr_1fr_1.15fr_auto] sm:items-end"><label className="block text-xs font-bold" htmlFor={`variant-size-${field.id}`}>Size<Input id={`variant-size-${field.id}`} className="mt-1.5 h-10 bg-card" placeholder="e.g. S" {...form.register(`variants.${index}.size`)} /></label><label className="block text-xs font-bold" htmlFor={`variant-sku-${field.id}`}>SKU <span className="font-normal text-muted-foreground">(internal code)</span><Input id={`variant-sku-${field.id}`} className="mt-1.5 h-10 bg-card" placeholder="e.g. BSIT-M-S" {...form.register(`variants.${index}.sku`)} /></label><label className="block text-xs font-bold" htmlFor={`variant-stock-${field.id}`}>Available now <span className="font-normal text-muted-foreground">(stock)</span><Input id={`variant-stock-${field.id}`} className="mt-1.5 h-10 bg-card" type="number" min="0" inputMode="numeric" {...form.register(`variants.${index}.quantity`, { setValueAs: toFormNumber })} /></label><label className="block text-xs font-bold" htmlFor={`variant-alert-${field.id}`}>Low-stock alert at<Input id={`variant-alert-${field.id}`} className="mt-1.5 h-10 bg-card" type="number" min="0" inputMode="numeric" {...form.register(`variants.${index}.lowStockThreshold`, { setValueAs: toFormNumber })} /></label><Button type="button" variant="ghost" disabled={variants.fields.length === 1} onClick={() => variants.remove(index)} className="h-10 text-xs text-destructive hover:bg-destructive/10 hover:text-destructive">Remove</Button></div><div className="mt-3 flex items-start gap-2 rounded-lg bg-card px-3 py-2 text-xs leading-5 text-muted-foreground"><CircleHelp aria-hidden="true" className="mt-0.5 size-3.5 shrink-0 text-primary" /><p><strong className="text-foreground">SKU</strong> is your own code for this exact size. <strong className="text-foreground">Available now</strong> is the number students can order. CampusWear shows <strong className="text-foreground">Low stock</strong> when available stock reaches your alert number.</p></div></div>)}</div>;
}

export default function VendorProducts() {
  const { user, loading } = useAuth();
  const queryClient = useQueryClient();
  const form = useForm<ProductForm>({ resolver: zodResolver(productSchema), defaultValues: { name: "", description: "", price: 0, variants: [{ size: "S", sku: "", quantity: 0, lowStockThreshold: 5 }, { size: "M", sku: "", quantity: 0, lowStockThreshold: 5 }, { size: "L", sku: "", quantity: 0, lowStockThreshold: 5 }] } });
  const variants = useFieldArray({ control: form.control, name: "variants" });
  const productsKey = vendorManagedProductsQueryKey(user?.id);
  const products = useQuery({ queryKey: productsKey, queryFn: listManagedProducts, enabled: !loading && Boolean(user?.id) });
  const create = useMutation({ mutationFn: createManagedProduct, onSuccess: async () => { toast.success("Product and sizes created."); form.reset(); await queryClient.invalidateQueries({ queryKey: productsKey }); }, onError: error => toast.error(error instanceof Error ? error.message : "The product could not be created.") });
  const upload = useMutation({ mutationFn: uploadProductImage, onSuccess: async () => { toast.success("Product photo updated."); await queryClient.invalidateQueries({ queryKey: productsKey }); await queryClient.invalidateQueries({ queryKey: ["supabase-catalog"] }); }, onError: error => toast.error(error instanceof Error ? error.message : "The product photo could not be uploaded.") });

  return <DashboardLayout items={vendorNavigation} primaryAction={vendorPrimaryAction} workspaceLabel="Vendor workspace"><WorkspaceGate allowedRoles={["vendor_staff", "platform_admin", "admin"]}><div className="mx-auto max-w-6xl"><PageIntro eyebrow="CATALOG MANAGEMENT" title="Products and stock" description="Create products, set each size’s available stock, and prepare a clear product photo before publishing to students." /><div className="mt-7 grid gap-6 xl:grid-cols-[0.95fr_1.05fr]"><section className="rounded-xl border border-border bg-card p-5 sm:p-7"><div className="flex gap-3"><span className="grid size-10 shrink-0 place-items-center rounded-xl bg-secondary text-primary"><Plus className="size-5" aria-hidden="true" /></span><div><h2 className="text-lg font-extrabold tracking-[-0.02em]">Add a product</h2><p className="mt-1 text-xs leading-5 text-muted-foreground">Start with the product details, then add every sellable size and its own stock amount.</p></div></div><form onSubmit={form.handleSubmit(values => create.mutate({ name: values.name, description: values.description, priceInCentavos: Math.round(values.price * 100), variants: values.variants }))} className="mt-6"><div className="grid gap-5 sm:grid-cols-2"><label className="block sm:col-span-2"><span className="text-sm font-extrabold">Product name <span className="text-destructive" aria-hidden="true">*</span></span><Input className="mt-2 min-h-11 bg-card" placeholder="e.g. BSIT Men's Uniform" {...form.register("name")} /><span className="mt-1.5 block text-xs text-destructive" role="alert">{form.formState.errors.name?.message}</span></label><label className="block sm:col-span-2"><span className="text-sm font-extrabold">Description <span className="text-destructive" aria-hidden="true">*</span></span><Textarea className="mt-2 min-h-24 bg-card" placeholder="Explain what the uniform or item includes." {...form.register("description")} /><span className="mt-1.5 block text-xs text-destructive" role="alert">{form.formState.errors.description?.message}</span></label><label className="block"><span className="text-sm font-extrabold">Price (PHP) <span className="text-destructive" aria-hidden="true">*</span></span><Input className="mt-2 min-h-11 bg-card" type="number" min="1" step="0.01" inputMode="decimal" {...form.register("price", { setValueAs: toFormNumber })} /><span className="mt-1.5 block text-xs text-destructive" role="alert">{form.formState.errors.price?.message}</span></label></div><div className="mt-7 border-t border-border pt-6"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><h3 className="font-extrabold">Sizes, SKU, and stock</h3><p className="mt-1 max-w-lg text-xs leading-5 text-muted-foreground">Each size needs its own internal SKU, available quantity, and low-stock alert number. Students see availability labels, not SKUs.</p></div><Button type="button" size="sm" variant="outline" onClick={() => variants.append({ size: "", sku: "", quantity: 0, lowStockThreshold: 5 })} className="w-fit gap-1.5"><Plus className="size-4" aria-hidden="true" />Add size</Button></div><VariantFields form={form} variants={variants} /></div><div className="mt-7 flex justify-end"><Button type="submit" disabled={create.isPending} className="w-full gap-2 sm:w-auto">{create.isPending ? "Creating product…" : "Create product"}<Plus className="size-4" aria-hidden="true" /></Button></div></form></section><section><div className="flex items-start justify-between gap-3"><div><h2 className="text-lg font-extrabold tracking-[-0.02em]">Your catalog</h2><p className="mt-1 text-xs leading-5 text-muted-foreground">These are the products and size-level stock labels students can see.</p></div><span className="rounded-full bg-secondary px-3 py-1 text-xs font-bold text-primary">{products.data?.length ?? 0} products</span></div>{products.isLoading ? <div className="mt-5 grid gap-3 sm:grid-cols-2"><div className="h-52 animate-pulse rounded-xl bg-muted" /><div className="h-52 animate-pulse rounded-xl bg-muted" /></div> : isStalledWithoutData(products) ? <div className="mt-5"><OfflinePanel title="You are offline" detail="Reconnect to load your product catalog." onRetry={() => products.refetch()} /></div> : products.isError ? <div className="mt-5"><EmptyPanel title="Catalog records are unavailable" detail="Refresh the workspace to try loading your products again." action={{ label: "Try again", onClick: () => products.refetch() }} /></div> : products.data?.length ? <div className="mt-5 grid gap-4 sm:grid-cols-2">{products.data.map((product, index) => <article key={product.id} className="rounded-xl border border-border bg-card overflow-hidden p-3 transition-shadow hover:shadow-[0_4px_12px_rgb(15_39_71/0.08)]"><ProductVisual name={product.name} imageUrl={product.imageUrl} index={index} className="aspect-[4/3] w-full rounded-xl" /><div className="px-1 pb-1 pt-4"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><h3 className="font-extrabold leading-5">{product.name}</h3><p className="mt-1 text-base font-extrabold tabular-nums text-primary">{formatPeso(product.priceInCentavos)}</p></div><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold ${product.isActive ? "bg-secondary text-campus-blue" : "bg-muted text-muted-foreground"}`}>{product.isActive ? "Visible" : "Hidden"}</span></div><p className="mt-2 line-clamp-2 text-xs leading-5 text-muted-foreground">{product.description}</p><div className="mt-4 space-y-2">{product.variants.map(variant => <div key={variant.id} className="flex items-center justify-between gap-2 rounded-xl border border-border bg-muted/35 px-3 py-2 text-xs"><span><strong>{variant.size}</strong><span className="text-muted-foreground"> · {variant.quantity} in stock</span></span><StatusBadge kind="inventory" value={variant.availability} /></div>)}</div><ProductPhotoAdjuster productName={product.name} isPending={upload.isPending} onSave={file => upload.mutate({ productId: product.id, file })} /><ProductEditor product={product} productsQueryKey={productsKey} /></div></article>)}</div> : <div className="mt-5"><EmptyPanel title="Your catalog is empty" detail="Create the first product and its sellable sizes from the form." /></div>}</section></div></div></WorkspaceGate></DashboardLayout>;
}
